(* [comment removed for export] *)
Definition clip_d (x s : Z) : Z := Z.max 0 x - Z.min 0 (s - Z.min 0 x).
Definition clip_s (x s : Z) : Z := Z.max 0 (s - Z.min 0 x).
Definition clip_w2 (x s w : Z) : Z := w + Z.min 0 x + Z.min 0 (s - Z.min 0 x).
Definition clip_w3 (x s w P : Z) : Z := clip_w2 x s w - Z.max 0 (clip_w2 x s w - P + clip_d x s).
Definition clip_w (x s w P Q : Z) : Z := clip_w3 x s w P - Z.max 0 (clip_s x s - Q + clip_w3 x s w P).

(* [comment removed for export] *)
Lemma clip_facts : forall x s w P Q, (0 <= P)%Z -> (0 <= Q)%Z -> (1 <= clip_w x s w P Q)%Z ->
  (0 <= clip_d x s)%Z /\ (0 <= clip_s x s)%Z /\ (clip_d x s + clip_w x s w P Q <= P)%Z /\ (clip_s x s + clip_w x s w P Q <= Q)%Z /\
  (clip_w x s w P Q <= w)%Z.
