Ltac fixv' v tac := lazymatch goal with |- msteps _ (mkst (regupd _ _ ?x) _ _ _) _ => first [ constr_eq x v | replace x with v by (symmetry; tac) ] end.
Ltac cu := unfold clip_w, clip_w3, clip_w2, clip_d, clip_s in *.
Ltac fsm x := fixv' (Z_to_bv 64 (if (x <? 0)%Z then -1 else 0)%Z) ltac:(apply srai63_Z; cu; lia).
Ltac fmin x := fixv' (Z_to_bv 64 (Z.min 0 x)) ltac:(apply and_smsk).
Ltac fmaxg x := fixv' (Z_to_bv 64 (Z.max 0 x)) ltac:(apply and_msk0).
Ltac fbit x := fixv' (Z_to_bv 64 (if (0 <? x)%Z then 1 else 0)%Z) ltac:(apply slt0_Z; cu; lia).
Ltac fmskw x := fixv' (Z_to_bv 64 (msk0 x)) ltac:(apply negw_bit).
Ltac fmsk x := fixv' (Z_to_bv 64 (msk0 x)) ltac:(apply neg_bit).
Ltac fsubw v := fixv' (Z_to_bv 64 v) ltac:(rewrite subw_fit by (cu; lia); f_equal; cu; lia).
Ltac faddw v := fixv' (Z_to_bv 64 v) ltac:(rewrite addw_fit by (cu; lia); f_equal; cu; lia).
Ltac fadd v := fixv' (Z_to_bv 64 v) ltac:(rewrite zbv_add; f_equal; cu; lia).
(* [comment removed for export] *)
Ltac condS := pin; rewrite ?c_lts_Zs by lia; first [ apply Z.ltb_lt | apply Z.ltb_ge ]; lia.

