(* [comment removed for export] *)
Lemma rl_A0g : forall regs m (s datad dpixw dx dw spixw sx : Z) (ret : word),
  (112 <= s)%Z -> (s + 64 < 2 ^ 64)%Z ->
  (0 <= dpixw < 2 ^ 31)%Z -> (- 2 ^ 31 <= dx < 2 ^ 31)%Z -> (- 2 ^ 31 <= dw < 2 ^ 31)%Z -> (0 <= spixw < 2 ^ 31)%Z -> (- 2 ^ 31 <= sx < 2 ^ 31)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 112 = true ->
  rdn SEGS m (Z_to_bv 64 (s + 24)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 spixw)) ->
  rdn SEGS m (Z_to_bv 64 (s + 48)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 sx)) ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 datad -> getr regs 11 = Z_to_bv 64 dpixw ->
  getr regs 13 = Z_to_bv 64 1 -> getr regs 15 = Z_to_bv 64 dx -> getr regs 17 = Z_to_bv 64 dw ->
  exists regs',
    msteps SEGS (mkst regs (0x79fb0 : word) m rom) (mkst regs' (0x7a010 : word) (RLF m s ret regs) rom)
