    /\ getr regs' 15 = Z_to_bv 64 dx /\ getr regs' 17 = Z_to_bv 64 dw /\ getr regs' 6 = Z_to_bv 64 spixw
    /\ getr regs' 7 = Z_to_bv 64 sx
    /\ regs_agree (fun r => In r [2; 5; 6; 7; 11; 15; 17; 28]%list) regs regs'.
