(* [comment removed for export] *)
Lemma rl_A1g_run : forall regs m (DX SX DW DPW SPW : Z),
  (- 2 ^ 24 <= DX <= 2 ^ 24)%Z -> (- 2 ^ 24 <= SX <= 2 ^ 24)%Z -> (0 <= DW <= 2 ^ 24)%Z -> (0 <= DPW <= 2 ^ 24)%Z -> (0 <= SPW <= 2 ^ 24)%Z ->
  getr regs 15 = Z_to_bv 64 DX -> getr regs 7 = Z_to_bv 64 SX -> getr regs 17 = Z_to_bv 64 DW -> getr regs 11 = Z_to_bv 64 DPW -> getr regs 6 = Z_to_bv 64 SPW ->
  exists regs',
    msteps SEGS (mkst regs (0x7a010 : word) m rom) (mkst regs' (0x7a078 : word) m rom)
    /\ getr regs' 19 = Z_to_bv 64 (clip_d DX SX) /\ getr regs' 26 = Z_to_bv 64 (clip_s DX SX) /\ getr regs' 6 = Z_to_bv 64 (clip_w DX SX DW DPW SPW)
