(* [comment removed for export] *)
Lemma rl_A2g_run : forall regs m (s dy sy dh dpixh spixh : Z),
  (112 <= s)%Z -> (s + 64 < 2 ^ 64)%Z ->
  (- 2 ^ 24 <= dy <= 2 ^ 24)%Z -> (- 2 ^ 24 <= sy <= 2 ^ 24)%Z -> (0 <= dh <= 2 ^ 24)%Z -> (0 <= dpixh <= 2 ^ 24)%Z -> (0 <= spixh <= 2 ^ 24)%Z ->
  rdn SEGS m (Z_to_bv 64 s) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 dh)) ->
  rdn SEGS m (Z_to_bv 64 (s + 32)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 spixh)) ->
  rdn SEGS m (Z_to_bv 64 (s + 56)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 sy)) ->
  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 16 = Z_to_bv 64 dy -> getr regs 12 = Z_to_bv 64 dpixh ->
  exists regs',
    msteps SEGS (mkst regs (0x7a080 : word) m rom) (mkst regs' (0x7a0f4 : word) m rom)
    /\ getr regs' 27 = Z_to_bv 64 (clip_d dy sy) /\ getr regs' 23 = Z_to_bv 64 (clip_s dy sy) /\ getr regs' 12 = Z_to_bv 64 (clip_w dy sy dh dpixh spixh)
